head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldstf07110";

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — param.listTpClssCd, param.section

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldstf07110.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_listTpClssCd_3", fn: function(){ return ((dma_pageContext.get("listTpClssCd") ?? "") === '02'); } }, { id: "if_acntclsMmdd1", fn: function(){ return ((dma_comInfo.get("acntclsMmdd1") ?? (() => { throw new Error("unresolved:" + "comInfo.acntclsMmdd1"); })()) !== ''); } }, { id: "if_secugrpId", fn: function(){ return ((dma_comInfo.get("secugrpId") ?? (() => { throw new Error("unresolved:" + "comInfo.secugrpId"); })()) !=='RT'); } }, { id: "if_exstStrtDd", fn: function(){ return ((dma_comInfo.get("exstStrtDd") ?? (() => { throw new Error("unresolved:" + "comInfo.exstStrtDd"); })()) !== ''); } }, { id: "if_exstEndDd", fn: function(){ return ((dma_comInfo.get("exstEndDd") ?? (() => { throw new Error("unresolved:" + "comInfo.exstEndDd"); })()) !== ''); } }, { id: "if_secugrpId_2", fn: function(){ return ((dma_comInfo.get("secugrpId") ?? (() => { throw new Error("unresolved:" + "comInfo.secugrpId"); })()) !=='RT'); } }, { id: "if_secugrpId_2", fn: function(){ return ((dma_pageContext.get("listTpClssCd") ?? "") ==='00' || (dma_pageContext.get("section") ?? "")==='00'); } }, { id: "if_ventStrtYymm", fn: function(){ return ((dma_comInfo.get("ventStrtYymm") ?? (() => { throw new Error("unresolved:" + "comInfo.ventStrtYymm"); })()) !== ''); } }, { id: "if_ventEndYymm", fn: function(){ return ((dma_comInfo.get("ventEndYymm") ?? (() => { throw new Error("unresolved:" + "comInfo.ventEndYymm"); })()) !== ''); } }, { id: "if_grenAuthStrtYymm", fn: function(){ return ((dma_comInfo.get("grenAuthStrtYymm") ?? (() => { throw new Error("unresolved:" + "comInfo.grenAuthStrtYymm"); })()) !== ''); } }, { id: "if_grenAuthEndYymm", fn: function(){ return ((dma_comInfo.get("grenAuthEndYymm") ?? (() => { throw new Error("unresolved:" + "comInfo.grenAuthEndYymm"); })()) !== ''); } }, { id: "if_innoBizAhthStrtYymm", fn: function(){ return ((dma_comInfo.get("innoBizAhthStrtYymm") ?? (() => { throw new Error("unresolved:" + "comInfo.innoBizAhthStrtYymm"); })()) !== ''); } }, { id: "if_innoBizAhthEndYymm", fn: function(){ return ((dma_comInfo.get("innoBizAhthEndYymm") ?? (() => { throw new Error("unresolved:" + "comInfo.innoBizAhthEndYymm"); })()) !== ''); } }, { id: "if_rsltNotiDd", fn: function(){ return ((dma_comInfo.get("rsltNotiDd") ?? (() => { throw new Error("unresolved:" + "comInfo.rsltNotiDd"); })()) !== ''); } }, { id: "if_ldMktTpCd", fn: function(){ return ((dma_comInfo.get("ldMktTpCd") ?? (() => { throw new Error("unresolved:" + "comInfo.ldMktTpCd"); })()) === '2' || (dma_comInfo.get("spotIsuTrdMktTpCd") ?? (() => { throw new Error("unresolved:" + "comInfo.spotIsuTrdMktTpCd"); })()) === '2' || (dma_comInfo.get("mktTpCd") ?? (() => { throw new Error("unresolved:" + "comInfo.mktTpCd"); })()) === '2'); } }, { id: "if_secugrpId_3", fn: function(){ return ((dma_comInfo.get("secugrpId") ?? (() => { throw new Error("unresolved:" + "comInfo.secugrpId"); })()) ==='FS'); } }, { id: "if_secugrpId_4", fn: function(){ return ((dma_comInfo.get("secugrpId") ?? (() => { throw new Error("unresolved:" + "comInfo.secugrpId"); })()) === 'DR'); } }, { id: "if_exstStrtDd_2", fn: function(){ return ((dma_comInfo.get("exstStrtDd") ?? (() => { throw new Error("unresolved:" + "comInfo.exstStrtDd"); })()) !== ''); } }, { id: "if_exstEndDd_2", fn: function(){ return ((dma_comInfo.get("exstEndDd") ?? (() => { throw new Error("unresolved:" + "comInfo.exstEndDd"); })()) !== ''); } }, { id: "if_acntclsMmdd1_2", fn: function(){ return ((dma_comInfo.get("acntclsMmdd1") ?? (() => { throw new Error("unresolved:" + "comInfo.acntclsMmdd1"); })()) !== ''); } }, { id: "if_acntclsMmdd2", fn: function(){ return ((dma_comInfo.get("acntclsMmdd2") ?? (() => { throw new Error("unresolved:" + "comInfo.acntclsMmdd2"); })()) !== ''); } }, { id: "if_acntclsMmdd3", fn: function(){ return ((dma_comInfo.get("acntclsMmdd3") ?? (() => { throw new Error("unresolved:" + "comInfo.acntclsMmdd3"); })()) !== ''); } }, { id: "if_acntclsMmdd4", fn: function(){ return ((dma_comInfo.get("acntclsMmdd4") ?? (() => { throw new Error("unresolved:" + "comInfo.acntclsMmdd4"); })()) !== ''); } }, { id: "if_secugrpId_5", fn: function(){ return ((dma_comInfo.get("secugrpId") ?? (() => { throw new Error("unresolved:" + "comInfo.secugrpId"); })()) === 'RT'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "__rb0", fn: function () { return "* 우회상장법인 정보(" + String(dma_commonInfo.get("apComNm")) + ")"; } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

// [A] 초기 목록 미해결 — jldstf07110: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_print_onclick
 * @description btn_print 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_print_onclick = function(e){
    try {
        fn_print()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf07110.btn_print_onclick' }); }
};

/**
 * @method
 * @name grd_mergeObjCorpList_oncellclick
 * @description grd_mergeObjCorpList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_mergeObjCorpList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_mergeObjCorpList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_mergeObjCorpList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        await scwin.openInfoWin1(); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_mergeObjCorpList.oncellclick' });
    }
};

/**
 * @method
 * @name btn_openInfoWin3_onclick
 * @description btn_openInfoWin3 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_openInfoWin3_onclick = async function(e){
    try {
        await scwin.openInfoWin3()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf07110.btn_openInfoWin3_onclick' }); }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name openInfoWin1
 * @description open Info Win1 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openInfoWin1 = async function () {
    const infoWin = {};
    const url = "/jldfil55300_1/jldfil55300_1.xml";
    const style = "dialogWidth:580px;dialogHeight:200px;scroll:no;resize:no";
    Object.assign(infoWin, (await $c.win.openPopup(url, { type: 'pageFramePopup', modal: true }, infoWin)) || {});
};

/**
 * @method
 * @name openInfoWin2
 * @description open Info Win2 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openInfoWin2 = async function () {
    const infoWin = {};
    const url = "/jldfil55300_2/jldfil55300_2.xml";
    const style = "dialogWidth:580px;dialogHeight:200px;scroll:no;resize:no";
    Object.assign(infoWin, (await $c.win.openPopup(url, { type: 'pageFramePopup', modal: true }, infoWin)) || {});
};

/**
 * @method
 * @name openInfoWin3
 * @description open Info Win3 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openInfoWin3 = async function () {
    const infoWin = {};
    const url = "/jldfil55300_3/jldfil55300_3.xml";
    const style = "dialogWidth:900px;dialogHeight:980px;scroll:no;resize:no";
    Object.assign(infoWin, (await $c.win.openPopup(url, { type: 'pageFramePopup', modal: true }, infoWin)) || {});
};
